import pandas as pd
import json
from pathlib import Path


# Input generated by Task 3
INPUT_FILE = Path("data/anomaly_predictions.csv")

# Output files
JSON_OUTPUT = Path("data/evaluation_results.json")
CSV_OUTPUT = Path("data/evaluation_summary.csv")


def evaluate_model():

    if not INPUT_FILE.exists():
        raise FileNotFoundError(
            f"Prediction file not found: {INPUT_FILE}"
        )

    df = pd.read_csv(INPUT_FILE)

    required_columns = [
        "prediction",
        "anomaly_score"
    ]

    missing = [
        col for col in required_columns
        if col not in df.columns
    ]

    if missing:
        raise ValueError(
            f"Missing required columns: {missing}"
        )

    total_events = len(df)

    normal_events = int(
        (df["prediction"] == "Normal").sum()
    )

    suspicious_events = int(
        (df["prediction"] == "Suspicious").sum()
    )

    anomaly_rate = (
        suspicious_events / total_events * 100
        if total_events > 0
        else 0
    )

    score_min = float(df["anomaly_score"].min())
    score_max = float(df["anomaly_score"].max())
    score_mean = float(df["anomaly_score"].mean())
    score_median = float(df["anomaly_score"].median())
    score_std = float(df["anomaly_score"].std())

    suspicious_df = df[
        df["prediction"] == "Suspicious"
    ]

    if len(suspicious_df) > 0:

        suspicious_score_mean = float(
            suspicious_df["anomaly_score"].mean()
        )

        suspicious_score_min = float(
            suspicious_df["anomaly_score"].min()
        )

        suspicious_score_max = float(
            suspicious_df["anomaly_score"].max()
        )

    else:

        suspicious_score_mean = None
        suspicious_score_min = None
        suspicious_score_max = None

    
    
    # Lower Isolation Forest decision_function score
    # means a stronger anomaly.
    top_anomalies = (
        df.sort_values(
            by="anomaly_score",
            ascending=True
        )
        .head(10)
    )

    top_anomalies_list = []

    for index, row in top_anomalies.iterrows():

        record = {
            "rank": len(top_anomalies_list) + 1,
            "anomaly_score": float(
                row["anomaly_score"]
            ),
            "prediction": row["prediction"]
        }

        # Include event ID if available
        if "event_id" in df.columns:
            record["event_id"] = row["event_id"]

        top_anomalies_list.append(record)

    event_type_analysis = []

    if "event_type_enc" in df.columns:

        grouped = df.groupby("event_type_enc")

        for event_type, group in grouped:

            total = len(group)

            suspicious = int(
                (group["prediction"] == "Suspicious").sum()
            )

            rate = (
                suspicious / total * 100
                if total > 0
                else 0
            )

            event_type_analysis.append({
                "event_type_enc": int(event_type),
                "total_events": int(total),
                "suspicious_events": suspicious,
                "anomaly_rate_percent": round(rate, 2)
            })

    severity_analysis = []

    if "severity_score" in df.columns:

        # Create four severity groups based on rank
        severity_rank = df["severity_score"].rank(
            method="average",
            pct=True
        )

        df["severity_band"] = pd.cut(
            severity_rank,
            bins=[0, 0.25, 0.50, 0.75, 1.0],
            labels=[
                "Lowest",
                "Lower-Middle",
                "Upper-Middle",
                "Highest"
            ],
            include_lowest=True
        )

        grouped = df.groupby(
            "severity_band",
            observed=False
        )

        for band, group in grouped:

            total = len(group)

            suspicious = int(
                (group["prediction"] == "Suspicious").sum()
            )

            rate = (
                suspicious / total * 100
                if total > 0
                else 0
            )

            severity_analysis.append({
                "severity_band": str(band),
                "total_events": int(total),
                "suspicious_events": suspicious,
                "anomaly_rate_percent": round(rate, 2)
            })

    results = {

        "model": "Isolation Forest",

        "evaluation_type":
            "Unsupervised Anomaly Detection",

        "total_events":
            total_events,

        "normal_events":
            normal_events,

        "suspicious_events":
            suspicious_events,

        "anomaly_rate_percent":
            round(anomaly_rate, 2),

        "ground_truth_available":
            False,

        "accuracy":
            None,

        "precision":
            None,

        "recall":
            None,

        "f1_score":
            None,

        "confusion_matrix":
            None,

        "anomaly_score_statistics": {

            "minimum":
                round(score_min, 6),

            "maximum":
                round(score_max, 6),

            "mean":
                round(score_mean, 6),

            "median":
                round(score_median, 6),

            "standard_deviation":
                round(score_std, 6)
        },

        "suspicious_score_statistics": {

            "minimum":
                suspicious_score_min,

            "maximum":
                suspicious_score_max,

            "mean":
                suspicious_score_mean
        },

        "top_anomalies":
            top_anomalies_list,

        "event_type_analysis":
            event_type_analysis,

        "severity_analysis":
            severity_analysis
    }

    JSON_OUTPUT.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    with open(
        JSON_OUTPUT,
        "w",
        encoding="utf-8"
    ) as file:

        json.dump(
            results,
            file,
            indent=4
        )

    summary = pd.DataFrame([{

        "model":
            "Isolation Forest",

        "total_events":
            total_events,

        "normal_events":
            normal_events,

        "suspicious_events":
            suspicious_events,

        "anomaly_rate_percent":
            round(anomaly_rate, 2),

        "score_min":
            round(score_min, 6),

        "score_max":
            round(score_max, 6),

        "score_mean":
            round(score_mean, 6),

        "score_median":
            round(score_median, 6),

        "score_std":
            round(score_std, 6)
    }])

    summary.to_csv(
        CSV_OUTPUT,
        index=False
    )

    # --------------------------------------------------------
    print("\n==========================================")
    print("     TASK 4 — MODEL EVALUATION")
    print("==========================================")

    print(f"Model              : Isolation Forest")
    print(f"Total Events       : {total_events}")
    print(f"Normal Events      : {normal_events}")
    print(f"Suspicious Events  : {suspicious_events}")
    print(f"Anomaly Rate       : {anomaly_rate:.2f}%")

    print("\nAnomaly Score Statistics")
    print("------------------------------------------")
    print(f"Minimum            : {score_min:.6f}")
    print(f"Maximum            : {score_max:.6f}")
    print(f"Mean               : {score_mean:.6f}")
    print(f"Median             : {score_median:.6f}")
    print(f"Std Deviation      : {score_std:.6f}")

    print("\nGround Truth        : Not Available")
    print("Accuracy            : N/A")
    print("Precision           : N/A")
    print("Recall              : N/A")
    print("F1 Score            : N/A")
    print("Confusion Matrix    : N/A")

    print("\nTop 10 anomalies:")
    print(
        top_anomalies[
            [c for c in
             ["event_id", "prediction", "anomaly_score"]
             if c in top_anomalies.columns]
        ].to_string(index=False)
    )

    print("\nEvaluation completed successfully.")

    print(f"\nSaved:")
    print(f"  {JSON_OUTPUT}")
    print(f"  {CSV_OUTPUT}")


if __name__ == "__main__":
    evaluate_model()